//! Regenerates the generated files of `nsh/bir` from the Rust modules and the names the old app calls.
//!
//! `cargo run --example door_types -- <bir folder> <name>...` writes `types.d.ts` (the `bir` module's
//! declarations) and `functions.ts` (one typed wrapper per host function in the names given that the
//! module has; a name it does not have is reported and skipped). `nsh/bir/regenerate.sh` runs it.

use std::collections::BTreeSet;
use std::path::PathBuf;

use bir_app_api::host::FunctionKind;
use nsh_app_ebirforms::door;

fn main() {
    let mut arguments = std::env::args().skip(1);
    let folder = PathBuf::from(
        arguments
            .next()
            .expect("usage: door_types <bir folder> <name>..."),
    );
    let wanted: BTreeSet<String> = arguments.collect();
    let functions = door::functions();
    let known: BTreeSet<&str> = functions.iter().map(|(name, _)| name.as_str()).collect();

    let unknown: Vec<&String> = wanted
        .iter()
        .filter(|name| !known.contains(name.as_str()))
        .collect();
    // Most of these are string literals that are not calls at all (colors, icons, keys); only the count is news.
    eprintln!(
        "{} names read from the old app are not host functions",
        unknown.len()
    );

    let used: Vec<&(String, FunctionKind)> = functions
        .iter()
        .filter(|(name, _)| wanted.contains(name))
        .collect();
    let unused: Vec<&str> = functions
        .iter()
        .filter(|(name, _)| !wanted.contains(name))
        .map(|(name, _)| name.as_str())
        .collect();

    std::fs::write(folder.join("types.d.ts"), door::types_file()).expect("write types.d.ts");

    let mut text = String::new();
    text.push_str(
        "// Generated by nsh/bir/regenerate.sh (cargo run --example door_types). Do not edit.\n\
         // One typed function per host function the old app calls (app/main.js, app/shell/*.js), named as the\n\
         // Rust module names it. Sync ones return the value, async ones a Promise. Types are in ./types.d.ts.\n\n\
         import { Door } from \"ebirforms/native\";\n\
         import type * as Host from \"./types\";\n\n",
    );
    for (name, kind) in &used {
        let (call, note) = match kind {
            FunctionKind::Sync => ("call", ""),
            FunctionKind::Async => ("callAsync", " (async)"),
        };
        let _ = note;
        text.push_str(&format!(
            "export const {name} = (...args: Parameters<typeof Host.{name}>): ReturnType<typeof Host.{name}> =>\n  Door.{call}(\"{name}\", args) as ReturnType<typeof Host.{name}>;\n\n"
        ));
    }
    // The interfaces and type aliases of the declarations, so a screen imports them from nsh/bir too.
    let types: Vec<String> = door::declared_types()
        .lines()
        .filter_map(|line| {
            let rest = line
                .strip_prefix("export interface ")
                .or_else(|| line.strip_prefix("export type "))?;
            let end = rest.find(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))?;
            Some(rest[..end].to_owned())
        })
        .collect();
    text.push_str("export type {\n");
    for name in &types {
        text.push_str(&format!("  {name},\n"));
    }
    text.push_str("} from \"./types\";\n\n");
    text.push_str(
        "/** Every wrapper above, for bir.system_info()-style calls. */\nexport const bir = {\n",
    );
    for (name, _) in &used {
        text.push_str(&format!("  {name},\n"));
    }
    text.push_str("} as const;\n\n");
    text.push_str("/** The names of the wrapped functions, with their kind, for tests. */\nexport const WRAPPED: readonly { name: string; kind: \"sync\" | \"async\" }[] = [\n");
    for (name, kind) in &used {
        let kind = match kind {
            FunctionKind::Sync => "sync",
            FunctionKind::Async => "async",
        };
        text.push_str(&format!("  {{ name: \"{name}\", kind: \"{kind}\" }},\n"));
    }
    text.push_str("];\n\n");
    text.push_str(&format!(
        "/** Host functions the old app never calls: not wrapped. */\nexport const NOT_WRAPPED: readonly string[] = [\n{}];\n",
        unused.iter().map(|name| format!("  \"{name}\",\n")).collect::<String>()
    ));
    std::fs::write(folder.join("functions.ts"), text).expect("write functions.ts");
    eprintln!(
        "wrote {} wrappers, {} not wrapped",
        used.len(),
        unused.len()
    );
}
